# apk.map — logical name -> real Alpine package(s).
# Only rows where the name actually differs from the logical name (§1); anything
# not listed passes through unchanged (zsh, git, curl, lsd, foot, unzip,
# fontconfig, fd are all identical on apk, so they need no row).

build = build-base
dev-headers = openssl-dev pkgconf
gh = github-cli
ghostty = source:provide_ghostty   # no native ghostty on Alpine
gtk4-dev = gtk4.0-dev
libadwaita-dev = libadwaita-dev
gettext = gettext-dev
